// 先看看当前环境：已装插件、DSH_HOME 配置
const installed = await tools.market_installed({ profile: "desktop" });
console.log("=== installed plugins (desktop) ===");
console.log(typeof installed === 'string' ? installed : JSON.stringify(installed, null, 2));

// 找 DSH_HOME 与配置目录
const r = await tools.pwsh({
  description: "查看 DSH_HOME 环境变量与配置目录",
  command: "$env:DSH_HOME; Test-Path $env:DSH_HOME; if (Test-Path $env:DSH_HOME) { Get-ChildItem $env:DSH_HOME | Select-Object Name, Mode | Format-Table -AutoSize | Out-String }"
});
console.log(r.stdout);
if (r.stderr && r.stderr.text) console.error("STDERR:", r.stderr.text);
